css:
color: var(--primaria);
border: 1px solid var(--primaria);
text-shadow: 0 0 8px color-mix(in srgb, var(--primaria) 70%, transparent);
box-shadow: 0 0 12px -2px color-mix(in srgb, var(--primaria) 60%, transparent),
            inset 0 0 10px -6px color-mix(in srgb, var(--primaria) 60%, transparent);
